#[allow(clippy::too_many_lines)]
fn flac_sub_frame_reader_restore_fixed(pool: &mut ConstantPool<'static>) -> Result<Attribute> {
    let mut instructions = Vec::new();
    let mut check_branches = Vec::new();
    let mut loop_exits = Vec::new();
    let mut frame_points = Vec::new();
    for order in 1..=4 {
        let check_target = instructions.len();
        if order > 1 {
            frame_points.push((check_target, false));
        }
        instructions.extend([
            Instruction::Iload_2,
            small_integer_instruction(order)?,
            Instruction::If_icmpne(0),
            small_integer_instruction(order)?,
            Instruction::Istore_3,
        ]);
        check_branches.push(instructions.len() - 3);
        let loop_target = instructions.len();
        frame_points.push((loop_target, true));
        instructions.extend([
            Instruction::Iload_3,
            Instruction::Iload_1,
            Instruction::If_icmpge(0),
            Instruction::Aload_0,
            Instruction::Iload_3,
            Instruction::Dup2,
            Instruction::Iaload,
        ]);
        loop_exits.push(instructions.len() - 5);
        match order {
            1 => instructions.extend([
                Instruction::Aload_0,
                Instruction::Iload_3,
                Instruction::Iconst_1,
                Instruction::Isub,
                Instruction::Iaload,
            ]),
            2 => instructions.extend([
                Instruction::Aload_0,
                Instruction::Iload_3,
                Instruction::Iconst_1,
                Instruction::Isub,
                Instruction::Iaload,
                Instruction::Iconst_1,
                Instruction::Ishl,
                Instruction::Aload_0,
                Instruction::Iload_3,
                Instruction::Iconst_2,
                Instruction::Isub,
                Instruction::Iaload,
                Instruction::Isub,
            ]),
            3 => instructions.extend([
                Instruction::Aload_0,
                Instruction::Iload_3,
                Instruction::Iconst_1,
                Instruction::Isub,
                Instruction::Iaload,
                Instruction::Aload_0,
                Instruction::Iload_3,
                Instruction::Iconst_2,
                Instruction::Isub,
                Instruction::Iaload,
                Instruction::Isub,
                Instruction::Dup,
                Instruction::Iconst_1,
                Instruction::Ishl,
                Instruction::Iadd,
                Instruction::Aload_0,
                Instruction::Iload_3,
                Instruction::Iconst_3,
                Instruction::Isub,
                Instruction::Iaload,
                Instruction::Iadd,
            ]),
            4 => instructions.extend([
                Instruction::Aload_0,
                Instruction::Iload_3,
                Instruction::Iconst_1,
                Instruction::Isub,
                Instruction::Iaload,
                Instruction::Aload_0,
                Instruction::Iload_3,
                Instruction::Iconst_3,
                Instruction::Isub,
                Instruction::Iaload,
                Instruction::Iadd,
                Instruction::Iconst_2,
                Instruction::Ishl,
                Instruction::Aload_0,
                Instruction::Iload_3,
                Instruction::Iconst_2,
                Instruction::Isub,
                Instruction::Iaload,
                Instruction::Iconst_2,
                Instruction::Ishl,
                Instruction::Aload_0,
                Instruction::Iload_3,
                Instruction::Iconst_2,
                Instruction::Isub,
                Instruction::Iaload,
                Instruction::Iconst_1,
                Instruction::Ishl,
                Instruction::Iadd,
                Instruction::Isub,
                Instruction::Aload_0,
                Instruction::Iload_3,
                Instruction::Iconst_4,
                Instruction::Isub,
                Instruction::Iaload,
                Instruction::Isub,
            ]),
            _ => unreachable!(),
        }
        instructions.extend([
            Instruction::Iadd,
            Instruction::Iastore,
            Instruction::Iinc(3, 1),
            Instruction::Goto(u16::try_from(loop_target)?),
        ]);
        let next_target = instructions.len();
        instructions[check_branches[order - 1]] =
            Instruction::If_icmpne(u16::try_from(next_target)?);
    }
    let return_target = instructions.len();
    instructions.push(Instruction::Return);
    for branch in loop_exits {
        instructions[branch] = Instruction::If_icmpge(u16::try_from(return_target)?);
    }
    let mut frames = Vec::new();
    let mut previous = None;
    for (target, append) in frame_points {
        let offset_delta = previous.map_or(target, |value| target - value - 1);
        frames.push(if append {
            StackFrame::AppendFrame {
                frame_type: 252,
                offset_delta: u16::try_from(offset_delta)?,
                locals: vec![VerificationType::Integer],
            }
        } else {
            StackFrame::ChopFrame {
                frame_type: 250,
                offset_delta: u16::try_from(offset_delta)?,
            }
        });
        previous = Some(target);
    }
    let offset_delta = return_target - previous.ok_or("missing fixed restore frame")? - 1;
    frames.push(StackFrame::ChopFrame {
        frame_type: 250,
        offset_delta: u16::try_from(offset_delta)?,
    });
    let mut body = code(pool, 8, 4, instructions)?;
    add_stack_map_table(pool, &mut body, frames)?;
    Ok(body)
}

