fn same_stack_frame(offset_delta: u16) -> StackFrame {
    if let Ok(frame_type) = u8::try_from(offset_delta)
        && frame_type <= 63
    {
        return StackFrame::SameFrame { frame_type };
    }
    StackFrame::SameFrameExtended {
        frame_type: 251,
        offset_delta,
    }
}

