fn add_track_enum_state(class: &mut ClassFile<'static>, class_name: &str) -> Result<()> {
    let constructor_descriptor = match class_name {
        TRACK_END_REASON_CLASS => "(Ljava/lang/String;IZ)V",
        YOUTUBE_ANDROID_VERSION_CLASS => "(Ljava/lang/String;ILjava/lang/String;I)V",
        YOUTUBE_FORMAT_INFO_CLASS => "(Ljava/lang/String;ILjava/lang/String;Ljava/lang/String;)V",
        _ => "(Ljava/lang/String;I)V",
    };
    let constructor = match class_name {
        TRACK_END_REASON_CLASS => end_reason_constructor(&mut class.constant_pool)?,
        YOUTUBE_ANDROID_VERSION_CLASS => {
            youtube_android_version_constructor(&mut class.constant_pool)?
        }
        YOUTUBE_FORMAT_INFO_CLASS => youtube_format_info_constructor(&mut class.constant_pool)?,
        _ => enum_constructor(&mut class.constant_pool)?,
    };
    add_method(
        class,
        MethodAccessFlags::PRIVATE,
        "<init>",
        constructor_descriptor,
        Some(constructor),
    )?;
    let initializer = if class_name == YOUTUBE_ANDROID_VERSION_CLASS {
        youtube_android_version_initializer(&mut class.constant_pool)?
    } else if class_name == YOUTUBE_FORMAT_INFO_CLASS {
        youtube_format_info_initializer(&mut class.constant_pool)?
    } else {
        track_enum_initializer(&mut class.constant_pool, class_name, constructor_descriptor)?
    };
    add_method(
        class,
        MethodAccessFlags::STATIC,
        "<clinit>",
        "()V",
        Some(initializer),
    )
}

fn add_delegated_audio_track_state(class: &mut ClassFile<'static>) -> Result<()> {
    let set_position = delegated_audio_track_set_position_fallback(&mut class.constant_pool)?;
    add_method(
        class,
        MethodAccessFlags::PRIVATE | MethodAccessFlags::SYNCHRONIZED,
        "mantleSetPositionFallback",
        "(J)V",
        Some(set_position),
    )?;
    for name in ["getDuration", "getPosition"] {
        let body = delegated_audio_track_get_long_fallback(&mut class.constant_pool, name)?;
        add_method(
            class,
            MethodAccessFlags::PRIVATE | MethodAccessFlags::SYNCHRONIZED,
            &format!("mantle{name}Fallback"),
            "()J",
            Some(body),
        )?;
    }
    Ok(())
}

fn delegated_audio_track_set_position_fallback(
    pool: &mut ConstantPool<'static>,
) -> Result<Attribute> {
    let owner = pool.add_class(DELEGATED_AUDIO_TRACK_CLASS)?;
    let delegate = pool.add_field_ref(
        owner,
        "delegate",
        "Lcom/sedmelluq/discord/lavaplayer/track/InternalAudioTrack;",
    )?;
    let internal = pool.add_class("com/sedmelluq/discord/lavaplayer/track/InternalAudioTrack")?;
    let set_position = pool.add_interface_method_ref(internal, "setPosition", "(J)V")?;
    let parent = pool.add_class(BASE_AUDIO_TRACK_CLASS)?;
    let fallback = pool.add_method_ref(parent, "setPosition", "(J)V")?;
    let mut body = code(
        pool,
        3,
        3,
        vec![
            Instruction::Aload_0,
            Instruction::Getfield(delegate),
            Instruction::Ifnull(8),
            Instruction::Aload_0,
            Instruction::Getfield(delegate),
            Instruction::Lload_1,
            Instruction::Invokeinterface(set_position, 3),
            Instruction::Return,
            Instruction::Aload_0,
            Instruction::Lload_1,
            Instruction::Invokespecial(fallback),
            Instruction::Return,
        ],
    )?;
    add_same_frame(pool, &mut body, 8)?;
    Ok(body)
}

fn delegated_audio_track_get_long_fallback(
    pool: &mut ConstantPool<'static>,
    name: &str,
) -> Result<Attribute> {
    let owner = pool.add_class(DELEGATED_AUDIO_TRACK_CLASS)?;
    let delegate = pool.add_field_ref(
        owner,
        "delegate",
        "Lcom/sedmelluq/discord/lavaplayer/track/InternalAudioTrack;",
    )?;
    let internal = pool.add_class("com/sedmelluq/discord/lavaplayer/track/InternalAudioTrack")?;
    let get = pool.add_interface_method_ref(internal, name, "()J")?;
    let parent = pool.add_class(BASE_AUDIO_TRACK_CLASS)?;
    let fallback = pool.add_method_ref(parent, name, "()J")?;
    let mut body = code(
        pool,
        2,
        1,
        vec![
            Instruction::Aload_0,
            Instruction::Getfield(delegate),
            Instruction::Ifnull(7),
            Instruction::Aload_0,
            Instruction::Getfield(delegate),
            Instruction::Invokeinterface(get, 1),
            Instruction::Lreturn,
            Instruction::Aload_0,
            Instruction::Invokespecial(fallback),
            Instruction::Lreturn,
        ],
    )?;
    add_same_frame(pool, &mut body, 7)?;
    Ok(body)
}

fn track_enum_initializer(
    pool: &mut ConstantPool<'static>,
    class_name: &str,
    constructor_descriptor: &str,
) -> Result<Attribute> {
    let constants = track_enum_constants(class_name).ok_or("unknown track enum")?;
    let owner = pool.add_class(class_name)?;
    let constructor = pool.add_method_ref(owner, "<init>", constructor_descriptor)?;
    let descriptor = format!("L{class_name};");
    let mut instructions = Vec::with_capacity(constants.len() * 7 + 1);
    for (ordinal, name) in constants.iter().enumerate() {
        instructions.extend([
            Instruction::New(owner),
            Instruction::Dup,
            Instruction::Ldc_w(pool.add_string(*name)?),
            small_integer_instruction(ordinal)?,
        ]);
        if class_name == TRACK_END_REASON_CLASS {
            instructions.push(if ordinal < 2 {
                Instruction::Iconst_1
            } else {
                Instruction::Iconst_0
            });
        }
        let field = pool.add_field_ref(owner, *name, &descriptor)?;
        instructions.extend([
            Instruction::Invokespecial(constructor),
            Instruction::Putstatic(field),
        ]);
    }
    instructions.push(Instruction::Return);
    code(
        pool,
        if class_name == TRACK_END_REASON_CLASS {
            5
        } else {
            4
        },
        0,
        instructions,
    )
}

